def count_regions(grid: list[list[int]]) -> int:
    if not grid:
        return 0
    regions = 0
    rows, cols = len(grid), len(grid[0])
    visited = set()
    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == 0 or (r, c) in visited:
            return
        visited.add((r, c))
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in visited:
                regions += 1
                dfs(r, c)
    return regions
